module PLL (
    input wire clk_in,
    input wire reset,
    input wire [3:0] divide,
    output reg clk_out,
    output reg locked
);
    reg [3:0] counter;
    reg [1:0] state; // 0: unlocked, 1: locking, 2: locked

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            counter <= 0;
            clk_out <= 0;
            state <= 0;
            locked <= 0;
        end else begin
            if (state == 0) begin // Unlocked
                counter <= 0;
                if (counter >= divide) begin
                    clk_out <= ~clk_out; // Toggle the output clock
                    state <= 1; // Move to locking state
                end else begin
                    counter <= counter + 1;
                end
            end else if (state == 1) begin // Locking
                if (counter >= divide) begin
                    clk_out <= ~clk_out;
                    state <= 2; // Move to locked state
                    locked <= 1; // PLL is locked
                end else begin
                    counter <= counter + 1;
                end
            end else if (state == 2) begin // Locked
                // PLL remains locked
            end
        end
    end
endmodule

