module pitch_detector(
    input clk,
    input reset,
    input audio_signal,
    output reg [7:0] frequency
);
    reg [7:0] zero_crossings;
    reg prev_signal;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            zero_crossings <= 8'b0;
            prev_signal <= 1'b0;
            frequency <= 8'b0;
        end else begin
