module instruction_pipeline (
    input clk,
    input rst,
    input [7:0] instruction,
    output reg [7:0] result
);
    reg [7:0] fetch_stage;
    reg [7:0] decode_stage;
    reg [7:0] execute_stage;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            fetch_stage <= 8'b0;
            decode_stage <= 8'b0;
            execute_stage <= 8'b0;
            result <= 8'b0;
        end else begin
            // Pipeline Stages
            fetch_stage <= instruction;         // Fetch instruction
            decode_stage <= fetch_stage;        // Decode instruction
            execute_stage <= decode_stage;      // Execute instruction
            result <= execute_stage;            // Output result
        end
    end
endmodule

