module uart_tx #(parameter BAUD_RATE = 9600, parameter CLOCK_FREQ = 50000000) (  
    input wire clk,  
    input wire rst,  
    input wire tx_en,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  

    localparam IDLE = 3'b000,  
               START_BIT = 3'b001,  
               DATA_BITS = 3'b010,  
               PARITY_BIT = 3'b011,  
               STOP_BIT = 3'b100;  

    reg [2:0] state;  
    reg [3:0] bit_count;  
    reg [15:0] clk_div;  
    reg parity;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            busy <= 0;  
            tx <= 1;  
            clk_div <= 0;  
            bit_count <= 0;  
            parity <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (tx_en) begin  
                        busy <= 1;  
                        state <= START_BIT;  
                        parity <= ^data_in;  
                    end  
                end  
                START_BIT: begin  
                    tx <= 0;  
                    if (clk_div < CLOCK_FREQ / BAUD_RATE)  
                        clk_div <= clk_div + 1;  
                    else begin  
                        clk_div <= 0;  
                        state <= DATA_BITS;  
                        bit_count <= 0;  
                    end  
                end  
                DATA_BITS: begin  
                    tx <= data_in[bit_count];  
                    if (clk_div < CLOCK_FREQ / BAUD_RATE)  
                        clk_div <= clk_div + 1;  
                    else begin  
                        clk_div <= 0;  
                        if (bit_count == 7)  
                            state <= PARITY_BIT;  
                        else  
                            bit_count <= bit_count + 1;  
                    end  
                end  
                PARITY_BIT: begin  
                    tx <= parity;  
                    if (clk_div < CLOCK_FREQ / BAUD_RATE)  
                        clk_div <= clk_div + 1;  
                    else begin  
                        clk_div <= 0;  
                        state <= STOP_BIT;  
                    end  
                end  
                STOP_BIT: begin  
                    tx <= 1;  
                    if (clk_div < CLOCK_FREQ / BAUD_RATE)  
                        clk_div <= clk_div + 1;  
                    else begin  
                        clk_div <= 0;  
                        busy <= 0;  
                        state <= IDLE;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

