module watchdog_timer (
    input wire clk,
    input wire reset,
    output reg timeout
);
    parameter TIMEOUT_LIMIT = 8'd100; // Example timeout limit
    reg [7:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 8'd0;
            timeout <= 1'b0;
        end else begin
            if (counter < TIMEOUT_LIMIT) begin
                counter <= counter + 1;
                timeout <= 1'b0;
            end else begin
                timeout <= 1'b1;
            end
        end
    end
endmodule

