    parameter TIMEOUT_PERIOD = 10;  
    reg [3:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout <= 0;  
        end else begin  
            if (kick) begin  
                counter <= 0;  
                timeout <= 0;  
            end else if (counter < TIMEOUT_PERIOD) begin  
                counter <= counter + 1;  
            end else begin  
                timeout <= 1;  
            end  
        end  
    end  
endmodule

