module vco (
    input wire clk,
    input wire reset,
    input wire [2:0] control_voltage,
    output reg vco_output
);
    reg [25:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            vco_output <= 0;
        end else begin
            counter <= counter + 1;
            if (counter >= (1 << (5 + control_voltage))) begin
                vco_output <= ~vco_output;
                counter <= 0;
            end
        end
    end
endmodule

